      // Already expanded or collapsed — try the chevron button
      const chevron = parentRow.locator("button").first();
      await chevron.click();
    }
    await childrenPromise;

    // Child should appear in the tree
    await expect(
      page.locator(`a[href="/issues/${childId}"]`)
    ).toBeVisible({ timeout: 10000 });
  });
});

